import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.D1iekJsc.js";const f=JSON.parse('{"title":"OpenRouter","description":"OpenRouter 無料モデル：公式 Free Models 合集、:free テキスト／視覚一覧、Key と枠、MiniTavern での記入。","frontmatter":{"title":"OpenRouter","description":"OpenRouter 無料モデル：公式 Free Models 合集、:free テキスト／視覚一覧、Key と枠、MiniTavern での記入。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"OpenRouter · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenRouter 無料モデル：公式 Free Models 合集、:free テキスト／視覚一覧、Key と枠、MiniTavern での記入。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/free-cloud/openrouter"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/free-cloud/openrouter"}]]},"headers":[],"relativePath":"ja/free-cloud/openrouter.md","filePath":"ja/free-cloud/openrouter.md","lastUpdated":1787224147000}'),d={name:"ja/free-cloud/openrouter.md"};function n(i,e,l,c,s,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h1><p>グローバルモデル集約ゲートウェイ：1 つの API Key で多数モデルを呼べる。うち一部が <strong>無料プール</strong>（モデル ID はしばしば <code>:free</code> 終わり、または公式 Free）。個人試用、開源モデル比較、低頻度ロールプレイ向き。公式合集：<a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a>；第三者まとめ <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a>（非公式、OpenRouter コンソールを正）。</p><blockquote><p>無料名簿、RPM／日リクエスト上限は変わる。<strong><a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models</a> とアカウントページを正</strong>とする。</p></blockquote><h2 id="公式と入口" tabindex="-1">公式と入口 <a class="header-anchor" href="#公式と入口" aria-label="Permalink to &quot;公式と入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>リソース</th><th>アドレス</th></tr></thead><tbody><tr><td>公式</td><td><a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a></td></tr><tr><td>API Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>Free Models 合集</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">openrouter.ai/collections/free-models</a></td></tr><tr><td>モデル広場（Free 絞り込み）</td><td><a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models?q=free</a></td></tr><tr><td>コミュニティまとめ（第三者）</td><td><a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr><tr><td>API Base URL</td><td><code>https://openrouter.ai/api/v1</code>（MiniTavern で <strong>OpenRouter</strong> 選択時は手入力不要なことが多い）</td></tr></tbody></table><h2 id="無料の取得" tabindex="-1">無料の取得 <a class="header-anchor" href="#無料の取得" aria-label="Permalink to &quot;無料の取得&quot;">​</a></h2><ol><li><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a> で登録し Key 作成（通常 <strong>クレジットカード不要</strong>）。</li><li><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> またはモデル広場で <strong>Model ID</strong> をコピー（<code>:free</code> 接尾辞に注意）。</li><li>MiniTavern でプラットフォーム <strong>OpenRouter</strong>、Key を貼り付け、モデルにその ID。</li></ol><table tabindex="0"><thead><tr><th>項目</th><th>説明</th></tr></thead><tbody><tr><td>無料方式</td><td>ID に <code>:free</code>、または合集で <code>$0</code> のモデル；自動ルーティング <code>openrouter/free</code> も可</td></tr><tr><td>限速参考</td><td>よく約 <strong>20 RPM／約 50 回／日</strong>；一括チャージ約 <strong>$10+</strong> 後、無料モデル日上限が約 <strong>1000 回／日</strong> まで上がる場合あり（公式準拠）</td></tr><tr><td>カード紐付け</td><td>無料帯は通常不要；チャージは枠引き上げまたは有料モデル用</td></tr><tr><td>プライバシー</td><td>一部無料上流はプロンプトでモデル改善の可能性；OpenRouter 設定でプライバシーオプションを確認。Poolside Laguna など無料帯は訓練利用の明記あり</td></tr></tbody></table><h2 id="モデル一覧" tabindex="-1">モデル一覧 <a class="header-anchor" href="#モデル一覧" aria-label="Permalink to &quot;モデル一覧&quot;">​</a></h2><p>合集と公開まとめのよくある <strong>テキスト／視覚</strong> ID（約 2026-08）；<strong>実態は公式準拠</strong>。ID は <strong>大文字小文字区別</strong>、<code>:free</code> は省略不可（その条目に接尾辞がない場合を除く）。</p><h3 id="テキスト-·-自動ルーティング" tabindex="-1">テキスト · 自動ルーティング <a class="header-anchor" href="#テキスト-·-自動ルーティング" aria-label="Permalink to &quot;テキスト · 自動ルーティング&quot;">​</a></h3><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>openrouter/free</code></td><td>リクエストごとに空き無料モデルを自動選択；最速導入、品質は固定しない</td></tr></tbody></table><h3 id="テキスト-·-汎用対話" tabindex="-1">テキスト · 汎用対話 <a class="header-anchor" href="#テキスト-·-汎用対話" aria-label="Permalink to &quot;テキスト · 汎用対話&quot;">​</a></h3><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>meta-llama/llama-3.3-70b-instruct:free</code></td><td>総合、多言語</td></tr><tr><td><code>meta-llama/llama-3.2-3b-instruct:free</code></td><td>軽量</td></tr><tr><td><code>openai/gpt-oss-20b:free</code> / <code>openai/gpt-oss-120b:free</code></td><td>OpenAI 開源重み MoE</td></tr><tr><td><code>google/gemma-3-27b-it:free</code> / <code>google/gemma-3-12b-it:free</code> / <code>google/gemma-3-4b-it:free</code></td><td>Gemma 3 系列</td></tr><tr><td><code>google/gemma-4-31b-it:free</code> / <code>google/gemma-4-26b-a4b-it:free</code></td><td>Gemma 4（一部視覚対応）</td></tr><tr><td><code>google/gemma-3n-e4b-it:free</code> / <code>google/gemma-3n-e2b-it:free</code></td><td>端側向け軽量</td></tr><tr><td><code>qwen/qwen3-next-80b-a3b-instruct:free</code></td><td>Qwen3 対話</td></tr><tr><td><code>z-ai/glm-4.5-air:free</code></td><td>GLM 軽量、中国語向き</td></tr><tr><td><code>minimax/minimax-m2.5:free</code></td><td>MiniMax</td></tr><tr><td><code>nousresearch/hermes-3-llama-3.1-405b:free</code></td><td>Hermes 3</td></tr><tr><td><code>arcee-ai/trinity-large-preview:free</code></td><td>Arcee Trinity Large Preview</td></tr><tr><td><code>openrouter/elephant-alpha</code></td><td>OpenRouter 托管テキスト（合集／広場が Free と記す場合）</td></tr><tr><td><code>cognitivecomputations/dolphin-mistral-24b-venice-edition:free</code></td><td>Venice Uncensored 変体（内容尺度は自己判断）</td></tr></tbody></table><h3 id="テキスト-·-推論-agent-コーディング" tabindex="-1">テキスト · 推論／Agent／コーディング <a class="header-anchor" href="#テキスト-·-推論-agent-コーディング" aria-label="Permalink to &quot;テキスト · 推論／Agent／コーディング&quot;">​</a></h3><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>qwen/qwen3-coder:free</code></td><td>Qwen3 Coder、コード向け</td></tr><tr><td><code>nvidia/nemotron-3-ultra:free</code>（または合集の現行 ID）</td><td>Nemotron 3 Ultra、長コンテキスト Agent</td></tr><tr><td><code>nvidia/nemotron-3.5-lightning:free</code></td><td>高スループット Agent</td></tr><tr><td><code>nvidia/nemotron-3-super-120b-a12b:free</code></td><td>Nemotron 3 Super</td></tr><tr><td><code>nvidia/nemotron-3-nano-30b-a3b:free</code> / <code>nvidia/nemotron-nano-9b-v2:free</code></td><td>Nano 系列</td></tr><tr><td><code>poolside/laguna-s-2.1:free</code> / <code>poolside/laguna-xs-2.1:free</code>（広場 ID 準拠）</td><td>Poolside コーディング Agent；無料帯は訓練利用の可能性</td></tr><tr><td><code>cohere/north-mini-code:free</code>（広場準拠）</td><td>Cohere North コーディング</td></tr><tr><td><code>liquid/lfm-2.5-1.2b-instruct:free</code> / <code>liquid/lfm-2.5-1.2b-thinking:free</code></td><td>Liquid 軽量</td></tr><tr><td><code>dots-studio/dots3-note-preview:free</code>（広場準拠）</td><td>Dots3-Note Preview</td></tr></tbody></table><p>合集の用量順は変わる；プログラミング向けは <a href="https://openrouter.ai/collections/coding" target="_blank" rel="noreferrer">Coding</a> で再度 Free を絞ることも可。</p><h3 id="テキスト-·-視覚-マルチモーダル入力" tabindex="-1">テキスト · 視覚（マルチモーダル入力） <a class="header-anchor" href="#テキスト-·-視覚-マルチモーダル入力" aria-label="Permalink to &quot;テキスト · 視覚（マルチモーダル入力）&quot;">​</a></h3><p>チャット主モデルが視覚対応なら、App で画像認識／マルチモーダル直送時に試せる：</p><table tabindex="0"><thead><tr><th>モデル ID</th><th>説明</th></tr></thead><tbody><tr><td><code>google/gemma-3-27b-it:free</code> など Gemma 3/4</td><td>文＋図入力</td></tr><tr><td><code>nvidia/nemotron-nano-12b-v2-vl:free</code></td><td>視覚／ドキュメント</td></tr><tr><td><code>nvidia/nemotron-3-nano-omni:free</code>（広場準拠）</td><td>マルチモーダル知覚</td></tr><tr><td><code>meta-llama/llama-guard-4-12b:free</code></td><td>安全分類向け、通常はチャット主モデルにしない</td></tr></tbody></table><h3 id="画像-動画" tabindex="-1">画像／動画 <a class="header-anchor" href="#画像-動画" aria-label="Permalink to &quot;画像／動画&quot;">​</a></h3><ul><li><strong>生図</strong>：OpenRouter <a href="https://openrouter.ai/collections/image-models" target="_blank" rel="noreferrer">Image Models</a>；無料かはモデルページの価格準拠。MiniTavern 画像接続は <strong>OpenRouter</strong> を選べる。</li><li><strong>動画</strong>：<a href="https://openrouter.ai/collections/video-models" target="_blank" rel="noreferrer">Video Models</a>；App に <strong>内蔵動画入口はない</strong>。</li><li>第三者一覧の Lyria などは音楽生成寄りで、チャット／生図とは無関係、対話モデルにしない。</li></ul><h2 id="minitavern-での記入" tabindex="-1">MiniTavern での記入 <a class="header-anchor" href="#minitavern-での記入" aria-label="Permalink to &quot;MiniTavern での記入&quot;">​</a></h2><p>一般手順は <a href="/ultra_guides/ja/manual/model-link">モデル接続</a>。</p><h3 id="チャット" tabindex="-1">チャット <a class="header-anchor" href="#チャット" aria-label="Permalink to &quot;チャット&quot;">​</a></h3><p>経路：<strong>設定 → モデル → モデル接続 → 新規</strong></p><ol><li>プラットフォーム <strong>OpenRouter</strong>（プリセット Base URL）</li><li>API Key を貼り付け</li><li>モデル ID 例 <code>meta-llama/llama-3.3-70b-instruct:free</code>、または <code>openrouter/free</code></li><li><strong>テスト</strong> → 成功後にデフォルトへ</li></ol><p><strong>カスタム (OpenAI)</strong>、Base URL <code>https://openrouter.ai/api/v1</code> でも近い効果；App プリセットを優先。</p><h3 id="画像生成" tabindex="-1">画像生成 <a class="header-anchor" href="#画像生成" aria-label="Permalink to &quot;画像生成&quot;">​</a></h3><p>経路：<strong>設定 → 画像生成 → 画像接続</strong> → プラットフォーム <strong>OpenRouter</strong>、広場で画像対応かつ無料（または課金可）の ID。より安定した無料生図は <a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a>、<a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a>。</p><h3 id="排錯" tabindex="-1">排錯 <a class="header-anchor" href="#排錯" aria-label="Permalink to &quot;排錯&quot;">​</a></h3><table tabindex="0"><thead><tr><th>現象</th><th>対処</th></tr></thead><tbody><tr><td><code>HTTP 429</code> / <code>Provider returned error</code></td><td>上流無料プール満杯または限流：他の <code>:free</code>、後で再試行、または <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a></td></tr><tr><td>国内アクセス失敗</td><td>公式 API はプロキシが必要な場合あり；国内直結ベンダー／<a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a> などへ</td></tr><tr><td>モデル 404／unavailable</td><td>その <code>:free</code> が下線：合集から ID を再コピー</td></tr></tbody></table><p>詳細は <a href="/ultra_guides/ja/manual/errors">エラー排錯</a>。</p><h2 id="関連章" tabindex="-1">関連章 <a class="header-anchor" href="#関連章" aria-label="Permalink to &quot;関連章&quot;">​</a></h2><ul><li><a href="/ultra_guides/ja/free-cloud/">無料クラウド総覧</a></li><li><a href="/ultra_guides/ja/free-cloud/freellm">FreeLLM 一覧</a> — より多くの無料ベンダー索引</li><li><a href="/ultra_guides/ja/free-cloud/aihubmix">AIHubMix</a> — 補助金型 <code>*-free</code>（一部閉源ミラー含む）</li><li><a href="/ultra_guides/ja/free-cloud/agnes-ai">Agnes AI</a> · <a href="/ultra_guides/ja/free-cloud/opencode-zen">OpenCode Zen</a></li><li><a href="/ultra_guides/ja/manual/model-link">モデル接続</a></li><li><a href="/ultra_guides/ja/free-cloud/#無料の画像生成">無料の画像生成</a></li></ul>',35)])])}const p=t(d,[["render",n]]);export{f as __pageData,p as default};
